ALTER TABLE public.workspaces ADD COLUMN attachment_limit_bytes bigint NOT NULL DEFAULT 10485760;
CREATE TABLE public.workspace_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,email text NOT NULL,role text NOT NULL,message text NOT NULL DEFAULT '',token_hash text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'Pending',expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',invited_by uuid NOT NULL REFERENCES public.profiles(id),accepted_by uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT invitation_role CHECK(role IN ('admin','member','viewer')),CONSTRAINT invitation_status CHECK(status IN ('Pending','Accepted','Expired','Revoked')));
GRANT SELECT(id,workspace_id,email,role,message,status,expires_at,invited_by,accepted_by,created_at,updated_at) ON public.workspace_invitations TO authenticated; GRANT ALL ON public.workspace_invitations TO service_role;
ALTER TABLE public.workspace_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY invitations_read ON public.workspace_invitations FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IN ('owner','admin'));
CREATE UNIQUE INDEX invitation_pending_email ON public.workspace_invitations(workspace_id,lower(email)) WHERE status='Pending';
CREATE TABLE public.task_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,project_id uuid NOT NULL,task_id uuid NOT NULL,author_id uuid NOT NULL REFERENCES public.profiles(id),parent_id uuid,content text NOT NULL,mention_ids uuid[] NOT NULL DEFAULT '{}',edited boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,task_id),FOREIGN KEY(task_id,project_id) REFERENCES public.tasks(id,project_id) ON DELETE CASCADE,FOREIGN KEY(project_id,workspace_id) REFERENCES public.projects(id,workspace_id) ON DELETE CASCADE,FOREIGN KEY(parent_id,task_id) REFERENCES public.task_comments(id,task_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.task_comments TO authenticated;GRANT ALL ON public.task_comments TO service_role;
ALTER TABLE public.task_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_read ON public.task_comments FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IS NOT NULL);
CREATE POLICY comments_create ON public.task_comments FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND public.workspace_role(workspace_id) IN ('owner','admin','member'));
CREATE POLICY comments_update ON public.task_comments FOR UPDATE TO authenticated USING(author_id=auth.uid() AND public.workspace_role(workspace_id) IN ('owner','admin','member')) WITH CHECK(author_id=auth.uid());
CREATE POLICY comments_delete ON public.task_comments FOR DELETE TO authenticated USING(author_id=auth.uid() AND public.workspace_role(workspace_id) IN ('owner','admin','member'));
CREATE INDEX comments_task_created ON public.task_comments(task_id,created_at,id);
CREATE TABLE public.attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,project_id uuid NOT NULL,task_id uuid,file_name text NOT NULL,mime_type text NOT NULL,byte_size bigint NOT NULL,storage_path text NOT NULL UNIQUE,uploaded_by uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'Pending',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,workspace_id) REFERENCES public.projects(id,workspace_id) ON DELETE CASCADE,FOREIGN KEY(task_id,project_id) REFERENCES public.tasks(id,project_id) ON DELETE CASCADE,CONSTRAINT attachment_status CHECK(status IN ('Pending','Ready','Deleting')));
GRANT SELECT ON public.attachments TO authenticated;GRANT ALL ON public.attachments TO service_role;
ALTER TABLE public.attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY attachments_read ON public.attachments FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IS NOT NULL AND (status='Ready' OR uploaded_by=auth.uid()));
CREATE INDEX attachments_project_created ON public.attachments(project_id,created_at,id);
CREATE TABLE public.notification_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,in_app jsonb NOT NULL DEFAULT '{"assignment":true,"mention":true,"comment":true,"project":true,"milestone":true,"deadline":true,"invitation":true}',email jsonb NOT NULL DEFAULT '{"assignment":true,"mention":true,"comment":false,"project":false,"milestone":false,"deadline":true,"invitation":true}',timezone text NOT NULL DEFAULT 'UTC',task_reminder_days integer NOT NULL DEFAULT 1,project_reminder_days integer NOT NULL DEFAULT 3,milestone_reminder_days integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.notification_preferences TO authenticated;GRANT ALL ON public.notification_preferences TO service_role;
ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY preferences_own ON public.notification_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,category text NOT NULL,title text NOT NULL,body text NOT NULL DEFAULT '',link text NOT NULL,event_key text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_key));
GRANT SELECT ON public.notifications TO authenticated;GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_own ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid() AND (public.workspace_role(workspace_id) IS NOT NULL OR category='invitation'));
CREATE INDEX notifications_user_created ON public.notifications(user_id,created_at DESC,id);
CREATE TABLE public.notification_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,recipient_email text NOT NULL,category text NOT NULL,title text NOT NULL,body text NOT NULL,link text NOT NULL,event_key text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'Pending',attempts integer NOT NULL DEFAULT 0,provider_id text,error text,next_attempt_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.notification_outbox TO service_role;
ALTER TABLE public.notification_outbox ENABLE ROW LEVEL SECURITY;
CREATE INDEX outbox_pending ON public.notification_outbox(status,next_attempt_at);
CREATE TABLE public.collaboration_activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,project_id uuid REFERENCES public.projects(id) ON DELETE CASCADE,task_id uuid REFERENCES public.tasks(id) ON DELETE SET NULL,actor_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,action text NOT NULL,entity_type text NOT NULL,entity_id uuid,title text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.collaboration_activity TO authenticated;GRANT ALL ON public.collaboration_activity TO service_role;
ALTER TABLE public.collaboration_activity ENABLE ROW LEVEL SECURITY;
CREATE POLICY collaboration_activity_read ON public.collaboration_activity FOR SELECT TO authenticated USING(public.workspace_role(workspace_id) IS NOT NULL);
CREATE INDEX collaboration_activity_workspace_created ON public.collaboration_activity(workspace_id,created_at DESC,id);
CREATE INDEX collaboration_activity_project_created ON public.collaboration_activity(project_id,created_at DESC,id);
CREATE FUNCTION public.guard_collaboration() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_TABLE_NAME='task_comments' THEN
 IF length(trim(NEW.content))<1 OR length(NEW.content)>10000 OR cardinality(NEW.mention_ids)>50 THEN RAISE EXCEPTION 'Comment must contain 1–10000 characters and at most 50 mentions'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(NEW.mention_ids) uid WHERE NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=NEW.workspace_id AND user_id=uid)) THEN RAISE EXCEPTION 'Mentioned user must belong to this workspace'; END IF;
 IF TG_OP='UPDATE' THEN IF NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id OR NEW.project_id<>OLD.project_id OR NEW.task_id<>OLD.task_id OR NEW.author_id<>OLD.author_id OR NEW.parent_id IS DISTINCT FROM OLD.parent_id OR NEW.created_at<>OLD.created_at THEN RAISE EXCEPTION 'Comment identity is immutable';END IF;NEW.edited:=true;ELSE NEW.edited:=false;NEW.created_at:=now();END IF;
 ELSIF TG_TABLE_NAME='notification_preferences' THEN
 IF NEW.task_reminder_days NOT BETWEEN 0 AND 14 OR NEW.project_reminder_days NOT BETWEEN 0 AND 14 OR NEW.milestone_reminder_days NOT BETWEEN 0 AND 14 OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.timezone) THEN RAISE EXCEPTION 'Invalid reminder timing or timezone';END IF;
 IF jsonb_typeof(NEW.in_app)<>'object' OR jsonb_typeof(NEW.email)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each(NEW.in_app||NEW.email) WHERE jsonb_typeof(value)<>'boolean' OR key NOT IN ('assignment','mention','comment','project','milestone','deadline','invitation')) THEN RAISE EXCEPTION 'Invalid notification preferences'; END IF;
 ELSIF TG_TABLE_NAME='workspaces' THEN IF NEW.attachment_limit_bytes NOT BETWEEN 1024 AND 10485760 THEN RAISE EXCEPTION 'Attachment limit must be between 1 KB and 10 MB'; END IF;
 END IF; NEW.updated_at:=now();RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.guard_collaboration() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER comments_guard BEFORE INSERT OR UPDATE ON public.task_comments FOR EACH ROW EXECUTE FUNCTION public.guard_collaboration();
CREATE TRIGGER preferences_guard BEFORE INSERT OR UPDATE ON public.notification_preferences FOR EACH ROW EXECUTE FUNCTION public.guard_collaboration();
CREATE TRIGGER workspace_attachment_limit BEFORE UPDATE ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.guard_collaboration();
CREATE FUNCTION public.enqueue_notification(p_workspace uuid,p_user uuid,p_category text,p_title text,p_body text,p_link text,p_key text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prefs public.notification_preferences;address text; BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=p_workspace AND user_id=p_user) THEN RETURN;END IF;
 SELECT * INTO prefs FROM public.notification_preferences WHERE user_id=p_user;
 IF coalesce((prefs.in_app->>p_category)::boolean,true) THEN INSERT INTO public.notifications(workspace_id,user_id,category,title,body,link,event_key) VALUES(p_workspace,p_user,p_category,p_title,p_body,p_link,p_key) ON CONFLICT(user_id,event_key) DO NOTHING;END IF;
 IF coalesce((prefs.email->>p_category)::boolean,p_category IN ('assignment','mention','deadline','invitation')) THEN SELECT email INTO address FROM public.profiles WHERE id=p_user;IF address IS NOT NULL THEN INSERT INTO public.notification_outbox(workspace_id,user_id,recipient_email,category,title,body,link,event_key) VALUES(p_workspace,p_user,address,p_category,p_title,p_body,p_link,p_user::text||':'||p_key) ON CONFLICT(event_key) DO NOTHING;END IF;END IF;
 END $$;
REVOKE ALL ON FUNCTION public.enqueue_notification(uuid,uuid,text,text,text,text,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.collaboration_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb;wid uuid;pid uuid;tid uuid;eid uuid;label text;event text;uid uuid;target text;BEGIN
 r:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;wid:=(r->>'workspace_id')::uuid;pid:=(r->>'project_id')::uuid;eid:=(r->>'id')::uuid;label:=coalesce(r->>'title',r->>'name',r->>'file_name',r->>'email',r->>'content','Workspace member');event:=TG_TABLE_NAME||' '||lower(TG_OP);tid:=CASE WHEN TG_TABLE_NAME='tasks' THEN eid ELSE (r->>'task_id')::uuid END;
 IF TG_TABLE_NAME='attachments' AND (TG_OP<>'UPDATE' OR NEW.status<>'Ready' OR OLD.status='Ready') THEN RETURN COALESCE(NEW,OLD);END IF;
 INSERT INTO public.collaboration_activity(workspace_id,project_id,task_id,actor_id,action,entity_type,entity_id,title,metadata) VALUES(wid,pid,CASE WHEN TG_OP='DELETE' AND TG_TABLE_NAME='tasks' THEN NULL ELSE tid END,auth.uid(),event,TG_TABLE_NAME,eid,left(label,300),jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE (to_jsonb(OLD)-'token_hash') END,'after',CASE WHEN TG_OP='DELETE' THEN NULL ELSE (to_jsonb(NEW)-'token_hash') END));
 target:=CASE WHEN tid IS NOT NULL THEN '/projects/'||pid||'/tasks/'||tid ELSE '/projects/'||coalesce(pid,eid)||'/overview' END;
 IF TG_TABLE_NAME='tasks' AND TG_OP<>'DELETE' THEN
 IF NEW.assignee_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.assignee_id IS DISTINCT FROM OLD.assignee_id) THEN PERFORM public.enqueue_notification(wid,NEW.assignee_id,'assignment','Task assigned: '||NEW.title,'You have been assigned this task',target,'assignment:'||eid||':'||NEW.version); END IF;
 IF TG_OP='UPDATE' AND NEW.assignee_id IS NOT NULL AND NEW.assignee_id IS DISTINCT FROM auth.uid() AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.due_date IS DISTINCT FROM OLD.due_date) THEN PERFORM public.enqueue_notification(wid,NEW.assignee_id,'project','Task updated: '||NEW.title,'Status or due date changed',target,'task-update:'||eid||':'||NEW.version);END IF;
 ELSIF TG_TABLE_NAME='task_comments' AND TG_OP<>'DELETE' THEN
 FOR uid IN SELECT DISTINCT unnest(NEW.mention_ids) LOOP IF uid<>NEW.author_id THEN PERFORM public.enqueue_notification(wid,uid,'mention','Mentioned in a task comment',left(NEW.content,300),target||'#discussion','mention:'||eid||':'||uid);END IF;END LOOP;
 IF TG_OP='INSERT' THEN FOR uid IN SELECT DISTINCT x FROM (SELECT assignee_id x FROM public.tasks WHERE id=tid UNION SELECT author_id FROM public.task_comments WHERE task_id=tid) q WHERE x IS NOT NULL AND x<>NEW.author_id AND NOT(x=ANY(NEW.mention_ids)) LOOP PERFORM public.enqueue_notification(wid,uid,'comment','New task comment',left(NEW.content,300),target||'#discussion','comment:'||eid||':'||uid);END LOOP;END IF;
 ELSIF TG_TABLE_NAME='projects' AND TG_OP='UPDATE' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.due_date IS DISTINCT FROM OLD.due_date) THEN FOR uid IN SELECT DISTINCT x FROM (SELECT NEW.owner_id x UNION SELECT user_id FROM public.project_members WHERE project_id=eid) q WHERE x IS DISTINCT FROM auth.uid() LOOP PERFORM public.enqueue_notification(wid,uid,'project','Project updated: '||NEW.name,'Project status or deadline changed','/projects/'||eid||'/overview','project:'||eid||':'||NEW.updated_at);END LOOP;
 ELSIF TG_TABLE_NAME='milestones' AND TG_OP<>'DELETE' AND NEW.owner_id IS NOT NULL AND NEW.owner_id IS DISTINCT FROM auth.uid() AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN PERFORM public.enqueue_notification(wid,NEW.owner_id,'milestone','Milestone: '||NEW.title,NEW.status,'/projects/'||pid||'/milestones','milestone:'||eid||':'||NEW.version);
 ELSIF TG_TABLE_NAME='workspace_members' AND TG_OP='UPDATE' AND NEW.role IS DISTINCT FROM OLD.role THEN PERFORM public.enqueue_notification(wid,NEW.user_id,'invitation','Workspace role changed',NEW.role,'/team','role:'||eid||':'||NEW.updated_at);
 END IF; RETURN COALESCE(NEW,OLD);END $$;
REVOKE ALL ON FUNCTION public.collaboration_event() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER collaboration_tasks AFTER INSERT OR UPDATE OR DELETE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.collaboration_event();
CREATE TRIGGER collaboration_projects AFTER INSERT OR UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.collaboration_event();
CREATE TRIGGER collaboration_milestones AFTER INSERT OR UPDATE ON public.milestones FOR EACH ROW EXECUTE FUNCTION public.collaboration_event();
CREATE TRIGGER collaboration_comments AFTER INSERT OR UPDATE OR DELETE ON public.task_comments FOR EACH ROW EXECUTE FUNCTION public.collaboration_event();
CREATE TRIGGER collaboration_files AFTER UPDATE ON public.attachments FOR EACH ROW EXECUTE FUNCTION public.collaboration_event();
CREATE TRIGGER collaboration_members AFTER INSERT OR UPDATE ON public.workspace_members FOR EACH ROW EXECUTE FUNCTION public.collaboration_event();
CREATE FUNCTION public.invite_workspace_member(p_workspace uuid,p_email text,p_role text,p_message text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token text;inv public.workspace_invitations;caller text;recipient uuid;BEGIN
 caller:=public.workspace_role(p_workspace);IF caller IS NULL OR caller NOT IN ('owner','admin') OR p_role NOT IN ('admin','member','viewer') OR (caller='admin' AND p_role='admin') THEN RAISE EXCEPTION 'Not authorized to invite this role';END IF;
 IF p_email IS NULL OR length(p_email)>254 OR trim(p_email)!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(coalesce(p_message,''))>2000 THEN RAISE EXCEPTION 'Invalid email or message';END IF;
 PERFORM 1 FROM public.workspaces WHERE id=p_workspace FOR UPDATE;
 SELECT id INTO recipient FROM public.profiles WHERE lower(email)=lower(trim(p_email));IF EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=p_workspace AND user_id=recipient) THEN RAISE EXCEPTION 'User is already a member';END IF;
 UPDATE public.workspace_invitations SET status='Expired',updated_at=now() WHERE workspace_id=p_workspace AND status='Pending' AND expires_at<=now();
 token:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
 INSERT INTO public.workspace_invitations(workspace_id,email,role,message,token_hash,invited_by) VALUES(p_workspace,lower(trim(p_email)),p_role,coalesce(p_message,''),encode(sha256(convert_to(token,'UTF8')),'hex'),auth.uid()) RETURNING * INTO inv;
 INSERT INTO public.notification_outbox(workspace_id,user_id,recipient_email,category,title,body,link,event_key) VALUES(p_workspace,recipient,inv.email,'invitation','Invitation to Planz',inv.message,'/invite#token='||token,'invite:'||inv.id);
 INSERT INTO public.collaboration_activity(workspace_id,actor_id,action,entity_type,entity_id,title) VALUES(p_workspace,auth.uid(),'Member invited','invitation',inv.id,inv.email);
 RETURN jsonb_build_object('id',inv.id,'token',token,'expires_at',inv.expires_at,'email_status','Pending');END $$;
REVOKE ALL ON FUNCTION public.invite_workspace_member(uuid,text,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.invite_workspace_member(uuid,text,text,text) TO authenticated;
CREATE FUNCTION public.revoke_workspace_invitation(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.workspace_invitations;BEGIN SELECT * INTO inv FROM public.workspace_invitations WHERE id=p_id FOR UPDATE;IF inv.id IS NULL OR public.workspace_role(inv.workspace_id) IS NULL OR public.workspace_role(inv.workspace_id) NOT IN ('owner','admin') OR (public.workspace_role(inv.workspace_id)='admin' AND inv.role='admin') THEN RAISE EXCEPTION 'Not authorized';END IF;UPDATE public.workspace_invitations SET status='Revoked',updated_at=now() WHERE id=p_id AND status='Pending';UPDATE public.notification_outbox SET status='Cancelled',updated_at=now() WHERE event_key='invite:'||p_id AND status IN ('Pending','Failed');END $$;
REVOKE ALL ON FUNCTION public.revoke_workspace_invitation(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.revoke_workspace_invitation(uuid) TO authenticated;
CREATE FUNCTION public.accept_workspace_invitation(p_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.workspace_invitations;address text;confirmed timestamptz;BEGIN
 IF auth.uid() IS NULL OR length(coalesce(p_token,''))<>64 THEN RAISE EXCEPTION 'Invalid invitation';END IF;
 SELECT email,email_confirmed_at INTO address,confirmed FROM auth.users WHERE id=auth.uid();
 SELECT * INTO inv FROM public.workspace_invitations WHERE token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') FOR UPDATE;
 IF inv.id IS NULL OR inv.status<>'Pending' OR inv.expires_at<=now() OR confirmed IS NULL OR lower(address)<>lower(inv.email) THEN RAISE EXCEPTION 'Invitation invalid, expired, used, or for another email';END IF;
 IF inv.role='admin' AND public.workspace_role(inv.workspace_id) IS NOT NULL THEN RAISE EXCEPTION 'Existing members must have their roles managed by the owner';END IF;
 INSERT INTO public.workspace_members(workspace_id,user_id,role) VALUES(inv.workspace_id,auth.uid(),inv.role) ON CONFLICT(workspace_id,user_id) DO NOTHING;
 UPDATE public.workspace_invitations SET status='Accepted',accepted_by=auth.uid(),updated_at=now() WHERE id=inv.id;
 PERFORM public.enqueue_notification(inv.workspace_id,inv.invited_by,'invitation','Invitation accepted',inv.email||' joined the workspace','/team','accepted:'||inv.id);
 RETURN inv.workspace_id;END $$;
REVOKE ALL ON FUNCTION public.accept_workspace_invitation(text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.accept_workspace_invitation(text) TO authenticated;
CREATE FUNCTION public.reserve_attachment(p_project uuid,p_task uuid,p_name text,p_mime text,p_size bigint) RETURNS public.attachments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid public.projects;limit_ bigint;a public.attachments;filename text;extension_ text;BEGIN
 SELECT * INTO pid FROM public.projects WHERE id=p_project;
 IF pid.id IS NULL OR public.workspace_role(pid.workspace_id) IS NULL OR public.workspace_role(pid.workspace_id) NOT IN ('owner','admin','member') THEN RAISE EXCEPTION 'Attachment upload not authorized';END IF;
 IF p_task IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=p_task AND project_id=p_project) THEN RAISE EXCEPTION 'Task belongs to another project';END IF;
 SELECT attachment_limit_bytes INTO limit_ FROM public.workspaces WHERE id=pid.workspace_id;
 filename:=left(regexp_replace(coalesce(p_name,''),'[^a-zA-Z0-9._ -]','_','g'),180);extension_:=lower(substring(filename from '\.([^.]+)$'));
 IF p_size IS NULL OR p_size<1 OR p_size>limit_ OR extension_ IS NULL OR NOT((extension_='pdf' AND p_mime='application/pdf') OR (extension_ IN ('png','jpg','jpeg') AND p_mime IN ('image/png','image/jpeg')) OR (extension_='txt' AND p_mime='text/plain') OR (extension_='csv' AND p_mime IN ('text/csv','application/vnd.ms-excel','text/plain')) OR (extension_='doc' AND p_mime='application/msword') OR (extension_='docx' AND p_mime='application/vnd.openxmlformats-officedocument.wordprocessingml.document') OR (extension_='xls' AND p_mime='application/vnd.ms-excel') OR (extension_='xlsx' AND p_mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') OR (extension_='ppt' AND p_mime='application/vnd.ms-powerpoint') OR (extension_='pptx' AND p_mime='application/vnd.openxmlformats-officedocument.presentationml.presentation')) THEN RAISE EXCEPTION 'Unsupported file type or size';END IF;
 a.id:=gen_random_uuid();INSERT INTO public.attachments(id,workspace_id,project_id,task_id,file_name,mime_type,byte_size,storage_path,uploaded_by) VALUES(a.id,pid.workspace_id,p_project,p_task,filename,p_mime,p_size,pid.workspace_id||'/'||p_project||'/'||a.id||'.'||extension_,auth.uid()) RETURNING * INTO a;RETURN a;END $$;
REVOKE ALL ON FUNCTION public.reserve_attachment(uuid,uuid,text,text,bigint) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.reserve_attachment(uuid,uuid,text,text,bigint) TO authenticated;
CREATE FUNCTION public.finish_attachment(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.attachments;BEGIN SELECT * INTO a FROM public.attachments WHERE id=p_id FOR UPDATE;IF a.id IS NULL OR a.uploaded_by<>auth.uid() OR public.workspace_role(a.workspace_id) IS NULL OR public.workspace_role(a.workspace_id) NOT IN ('owner','admin','member') THEN RAISE EXCEPTION 'Not authorized';END IF;IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='workspace-files' AND name=a.storage_path AND (metadata->>'size')::bigint=a.byte_size AND metadata->>'mimetype'=a.mime_type) THEN RAISE EXCEPTION 'Uploaded file metadata does not match';END IF;UPDATE public.attachments SET status='Ready',updated_at=now() WHERE id=p_id AND status='Pending';END $$;
REVOKE ALL ON FUNCTION public.finish_attachment(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finish_attachment(uuid) TO authenticated;
CREATE FUNCTION public.remove_attachment(p_id uuid,p_finish boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.attachments;role_ text;BEGIN SELECT * INTO a FROM public.attachments WHERE id=p_id FOR UPDATE;role_:=public.workspace_role(a.workspace_id);IF a.id IS NULL OR role_ IS NULL OR role_ NOT IN ('owner','admin','member') OR (a.uploaded_by<>auth.uid() AND role_ NOT IN ('owner','admin')) THEN RAISE EXCEPTION 'Not authorized to delete attachment';END IF;IF p_finish THEN IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='workspace-files' AND name=a.storage_path) THEN RAISE EXCEPTION 'Remove stored file first';END IF;DELETE FROM public.attachments WHERE id=p_id;ELSE UPDATE public.attachments SET status='Deleting',updated_at=now() WHERE id=p_id;END IF;END $$;
REVOKE ALL ON FUNCTION public.remove_attachment(uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.remove_attachment(uuid,boolean) TO authenticated;
CREATE POLICY workspace_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='workspace-files' AND EXISTS(SELECT 1 FROM public.attachments a WHERE a.storage_path=name AND public.workspace_role(a.workspace_id) IS NOT NULL AND (a.status='Ready' OR a.uploaded_by=auth.uid())));
CREATE POLICY workspace_files_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='workspace-files' AND EXISTS(SELECT 1 FROM public.attachments a WHERE a.storage_path=name AND a.status='Pending' AND a.uploaded_by=auth.uid() AND public.workspace_role(a.workspace_id) IN ('owner','admin','member') AND (metadata->>'size')::bigint=a.byte_size AND metadata->>'mimetype'=a.mime_type));
CREATE POLICY workspace_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='workspace-files' AND EXISTS(SELECT 1 FROM public.attachments a WHERE a.storage_path=name AND a.status='Deleting' AND public.workspace_role(a.workspace_id) IN ('owner','admin','member') AND (a.uploaded_by=auth.uid() OR public.workspace_role(a.workspace_id) IN ('owner','admin'))));
CREATE FUNCTION public.mark_notifications(p_id uuid DEFAULT NULL,p_read boolean DEFAULT true) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated';END IF;UPDATE public.notifications SET read_at=CASE WHEN p_read THEN now() ELSE NULL END,updated_at=now() WHERE user_id=auth.uid() AND (p_id IS NULL OR id=p_id);END $$;
REVOKE ALL ON FUNCTION public.mark_notifications(uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.mark_notifications(uuid,boolean) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications,public.task_comments;
CREATE FUNCTION public.process_deadline_reminders() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;today_ date;lead integer;sent integer:=0;BEGIN
 UPDATE public.workspace_invitations SET status='Expired',updated_at=now() WHERE status='Pending' AND expires_at<=now();
 FOR r IN SELECT t.workspace_id,t.project_id,t.id,t.assignee_id uid,t.title,t.due_date,'task' kind FROM public.tasks t JOIN public.projects p ON p.id=t.project_id WHERE t.status<>'done' AND p.status NOT IN ('Completed','Archived') AND t.due_date IS NOT NULL AND t.assignee_id IS NOT NULL UNION ALL SELECT p.workspace_id,p.id,p.id,p.owner_id,p.name,p.due_date,'project' FROM public.projects p WHERE p.status NOT IN ('Completed','Archived') AND p.due_date IS NOT NULL UNION ALL SELECT m.workspace_id,m.project_id,m.id,m.owner_id,m.title,m.due_date,'milestone' FROM public.milestones m JOIN public.projects p ON p.id=m.project_id WHERE m.status<>'Completed' AND p.status NOT IN ('Completed','Archived') AND m.owner_id IS NOT NULL AND m.due_date IS NOT NULL LOOP
 SELECT (now() AT TIME ZONE coalesce(np.timezone,'UTC'))::date,CASE r.kind WHEN 'task' THEN coalesce(np.task_reminder_days,1) WHEN 'project' THEN coalesce(np.project_reminder_days,3) ELSE coalesce(np.milestone_reminder_days,1) END INTO today_,lead FROM (SELECT 1) q LEFT JOIN public.notification_preferences np ON np.user_id=r.uid;
 IF r.due_date BETWEEN today_-1 AND today_+lead THEN PERFORM public.enqueue_notification(r.workspace_id,r.uid,'deadline',CASE WHEN r.due_date<today_ THEN 'Overdue: ' ELSE 'Deadline: ' END||r.title,r.due_date::text,CASE r.kind WHEN 'task' THEN '/projects/'||r.project_id||'/tasks/'||r.id WHEN 'milestone' THEN '/projects/'||r.project_id||'/milestones' ELSE '/projects/'||r.project_id||'/overview' END,'deadline:'||r.kind||':'||r.id||':'||r.due_date||':'||CASE WHEN r.due_date<today_ THEN 'overdue' ELSE 'upcoming' END);sent:=sent+1;END IF;
 END LOOP;RETURN sent;END $$;
REVOKE ALL ON FUNCTION public.process_deadline_reminders() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.process_deadline_reminders() TO service_role;